use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Seek, SeekFrom, Write};
use std::path::Path;

type ByteString = Vec<u8>;
type ByteStr = [u8];

pub struct KeyValuePair {
    pub key: ByteString,
    pub value: ByteString,
}

pub struct ActionKV {
    f: File,
    pub index: HashMap<ByteString, u64>,
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = !0u32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            crc = (crc >> 1) ^ (0xEDB8_8320 & (crc & 1).wrapping_neg());
        }
    }
    !crc
}

fn read_u32<R: Read>(f: &mut R) -> io::Result<u32> {
    let mut b = [0u8; 4];
    f.read_exact(&mut b)?;
    Ok(u32::from_le_bytes(b))
}

impl ActionKV {
    pub fn open(path: &Path) -> io::Result<Self> {
        let f = OpenOptions::new().read(true).write(true).create(true).append(true).open(path)?;
        Ok(ActionKV { f, index: HashMap::new() })
    }

    fn process_record<R: Read>(f: &mut R) -> io::Result<KeyValuePair> {
        let saved_checksum = read_u32(f)?;
        let key_len = read_u32(f)?;
        let val_len = read_u32(f)?;
        let data_len = key_len + val_len;

        let mut data = ByteString::with_capacity(data_len as usize);
        f.by_ref().take(data_len as u64).read_to_end(&mut data)?;
        debug_assert_eq!(data.len(), data_len as usize);

        let checksum = crc32(&data);
        if checksum != saved_checksum {
            panic!("data corruption encountered ({:08x} != {:08x})", checksum, saved_checksum);
        }

        let value = data.split_off(key_len as usize);
        let key = data;
        Ok(KeyValuePair { key, value })
    }

    pub fn load(&mut self) -> io::Result<()> {
        let mut f = BufReader::new(&mut self.f);
        f.seek(SeekFrom::Start(0))?;
        loop {
            let position = f.stream_position()?;
            let kv = match ActionKV::process_record(&mut f) {
                Ok(kv) => kv,
                Err(err) => match err.kind() {
                    io::ErrorKind::UnexpectedEof => break,
                    _ => return Err(err),
                },
            };
            self.index.insert(kv.key, position);
        }
        Ok(())
    }

    pub fn get(&mut self, key: &ByteStr) -> io::Result<Option<ByteString>> {
        let position = match self.index.get(key) {
            None => return Ok(None),
            Some(position) => *position,
        };
        let kv = self.get_at(position)?;
        // an empty value is a tombstone left by delete
        Ok(if kv.value.is_empty() { None } else { Some(kv.value) })
    }

    pub fn get_at(&mut self, position: u64) -> io::Result<KeyValuePair> {
        let mut f = BufReader::new(&mut self.f);
        f.seek(SeekFrom::Start(position))?;
        ActionKV::process_record(&mut f)
    }

    pub fn insert(&mut self, key: &ByteStr, value: &ByteStr) -> io::Result<()> {
        let position = self.insert_but_ignore_index(key, value)?;
        self.index.insert(key.to_vec(), position);
        Ok(())
    }

    fn insert_but_ignore_index(&mut self, key: &ByteStr, value: &ByteStr) -> io::Result<u64> {
        let key_len = key.len();
        let val_len = value.len();
        let mut tmp = ByteString::with_capacity(key_len + val_len);
        tmp.extend_from_slice(key);
        tmp.extend_from_slice(value);
        let checksum = crc32(&tmp);

        let position = self.f.seek(SeekFrom::End(0))?;
        let mut f = BufWriter::new(&mut self.f);
        f.write_all(&checksum.to_le_bytes())?;
        f.write_all(&(key_len as u32).to_le_bytes())?;
        f.write_all(&(val_len as u32).to_le_bytes())?;
        f.write_all(&tmp)?;
        f.flush()?;
        Ok(position)
    }

    #[inline]
    pub fn update(&mut self, key: &ByteStr, value: &ByteStr) -> io::Result<()> {
        self.insert(key, value)
    }

    #[inline]
    pub fn delete(&mut self, key: &ByteStr) -> io::Result<()> {
        self.insert(key, b"")
    }
}

fn main() -> io::Result<()> {
    let path = std::env::temp_dir().join(format!("akv-{}.db", std::process::id()));
    let _ = std::fs::remove_file(&path);

    {
        let mut store = ActionKV::open(&path)?;
        store.load()?;
        store.insert(b"Fiji", b"Suva")?;
        store.insert(b"Kiribati", b"South Tarawa")?;
        store.insert(b"Cook Islands", b"Avarua")?;
        store.update(b"Kiribati", b"Tarawa")?;
        store.delete(b"Cook Islands")?;
    } // the store is dropped: only the file remains

    let mut store = ActionKV::open(&path)?;
    store.load()?;
    for key in [&b"Fiji"[..], b"Kiribati", b"Cook Islands"] {
        match store.get(key)? {
            Some(v) => println!("{} -> {}", String::from_utf8_lossy(key), String::from_utf8_lossy(&v)),
            None => println!("{} not found", String::from_utf8_lossy(key)),
        }
    }
    println!("{} records on disk, {} bytes", 5, std::fs::metadata(&path)?.len());
    std::fs::remove_file(&path)?;
    Ok(())
}

use std::collections::BTreeMap;

fn main() {
    let mut voc = BTreeMap::new();
    voc.insert(3_697_915, "Amsterdam");
    voc.insert(1_300_405, "Middelburg");
    voc.insert(540_000, "Enkhuizen");
    voc.insert(469_400, "Delft");
    voc.insert(266_868, "Hoorn");
    voc.insert(173_000, "Rotterdam");

    for (guilders, kamer) in &voc {
        println!("{kamer} invested {guilders}");
    }

    print!("smaller chambers: ");
    for (_guilders, kamer) in voc.range(0..500_000) {
        print!("{kamer} ");
    }
    println!();
}

